const [toasts, setToasts] = useState<ToastItem[]>([])
const dismiss = (id: string) => { setToasts((list) => list.filter((t) => t.id !== id)) }
const publish = () => {
  const id = `t${String(Date.now())}`
  setToasts((list) => [
    ...list,
    {
      id,
      tone: 'success',
      title: 'Report published',
      description: 'Everyone on the workspace can open it now.',action: { label: 'Undo', onAction: () => undefined },
    },
  ])
}

<>
  <Button onClick={publish}>Publish report</Button>
  <ToastStack toasts={toasts} onDismiss={dismiss} />
</>
